DROP TABLE IF EXISTS "public"."chan_structure";

CREATE TABLE "public"."chan_structure" (
  "code" character varying NOT NULL,
  "kl_type" character varying NOT NULL,
  "autype" character varying NOT NULL DEFAULT 'QFQ'::character varying,
  "structure" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "updated_at" timestamp with time zone NOT NULL DEFAULT now(),
  PRIMARY KEY ("code", "kl_type", "autype")
);
CREATE INDEX "idx_cs_code" ON "public"."chan_structure" USING btree ("code");

DROP TABLE IF EXISTS "public"."chan_user";

CREATE SEQUENCE IF NOT EXISTS "public"."chan_user_id_seq"
  AS integer
  START WITH 1
  INCREMENT BY 1
  MINVALUE 1
  MAXVALUE 2147483647
  CACHE 1
  NO CYCLE;

CREATE TABLE "public"."chan_user" (
  "id" serial NOT NULL,
  "username" character varying NOT NULL,
  "password" character varying NOT NULL,
  "nickname" character varying NOT NULL,
  "role" character varying NOT NULL DEFAULT 'viewer'::character varying,
  "status" character varying NOT NULL DEFAULT 'active'::character varying,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at" timestamp with time zone NOT NULL DEFAULT now(),
  PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "chan_user_username_key" ON "public"."chan_user" USING btree ("username");

