DROP TABLE IF EXISTS "public"."monitor";

CREATE SEQUENCE IF NOT EXISTS "public"."monitor_id_seq"
  AS integer
  START WITH 1
  INCREMENT BY 1
  MINVALUE 1
  MAXVALUE 2147483647
  CACHE 1
  NO CYCLE;

CREATE TABLE "public"."monitor" (
  "id" serial NOT NULL,
  "code" character varying NOT NULL,
  "kl_type" character varying NOT NULL,
  "monitor_start_time" character varying NOT NULL,
  "entry_price" double precision NOT NULL,
  "status" character varying NOT NULL DEFAULT 'monitoring'::character varying,
  "sold_price" double precision,
  "sold_at" timestamp with time zone,
  "pnl_pct" double precision,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  PRIMARY KEY ("id")
);
CREATE INDEX "idx_monitor_code" ON "public"."monitor" USING btree ("code");
CREATE INDEX "idx_monitor_status" ON "public"."monitor" USING btree ("status");

DROP TABLE IF EXISTS "public"."permission";

CREATE SEQUENCE IF NOT EXISTS "public"."permission_id_seq"
  AS integer
  START WITH 1
  INCREMENT BY 1
  MINVALUE 1
  MAXVALUE 2147483647
  CACHE 1
  NO CYCLE;

CREATE TABLE "public"."permission" (
  "id" serial NOT NULL,
  "code" character varying NOT NULL,
  "name" character varying NOT NULL DEFAULT ''::character varying,
  "type" character varying NOT NULL DEFAULT 'menu'::character varying,
  PRIMARY KEY ("id"),
  CONSTRAINT "chk_perm_type" CHECK (type::text = ANY (ARRAY['menu'::character varying, 'button'::character varying]::text[]))
);
CREATE UNIQUE INDEX "uq_perm_code" ON "public"."permission" USING btree ("code");

