DROP TABLE IF EXISTS "public"."stock";

CREATE TABLE "public"."stock" (
  "code" character varying NOT NULL,
  "name" character varying NOT NULL DEFAULT ''::character varying,
  "exchange" character varying NOT NULL DEFAULT ''::character varying,
  "enabled" boolean NOT NULL DEFAULT true,
  "kl_types" character varying[] NOT NULL DEFAULT '{}'::character varying[],
  "autypes" character varying[] NOT NULL DEFAULT '{}'::character varying[],
  "tags" character varying[] NOT NULL DEFAULT '{}'::character varying[],
  "notes" text NOT NULL DEFAULT ''::text,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at" timestamp with time zone NOT NULL DEFAULT now(),
  "ipo_date" date,
  "board" character varying NOT NULL DEFAULT ''::character varying,
  "industry_l1" character varying NOT NULL DEFAULT ''::character varying,
  "full_name" character varying NOT NULL DEFAULT ''::character varying,
  "en_name" character varying NOT NULL DEFAULT ''::character varying,
  "former_names" text NOT NULL DEFAULT ''::text,
  "legal_person" character varying NOT NULL DEFAULT ''::character varying,
  "reg_capital" character varying NOT NULL DEFAULT ''::character varying,
  "found_date" date,
  "website" character varying NOT NULL DEFAULT ''::character varying,
  "email" character varying NOT NULL DEFAULT ''::character varying,
  "phone" character varying NOT NULL DEFAULT ''::character varying,
  "reg_addr" text NOT NULL DEFAULT ''::text,
  "office_addr" text NOT NULL DEFAULT ''::text,
  "postal_code" character varying NOT NULL DEFAULT ''::character varying,
  "main_business" text NOT NULL DEFAULT ''::text,
  "business_scope" text NOT NULL DEFAULT ''::text,
  "intro" text NOT NULL DEFAULT ''::text,
  "price" numeric(12,4),
  "total_mv" numeric(18,4),
  "float_mv" numeric(18,4),
  "pe_ttm" numeric(14,4),
  "pb" numeric(14,4),
  "turnover_rate" numeric(10,4),
  "main_net_inflow" numeric(18,4),
  "snapshot_at" timestamp with time zone,
  "fax" character varying NOT NULL DEFAULT ''::character varying,
  "name_py" character varying NOT NULL DEFAULT ''::character varying,
  PRIMARY KEY ("code")
);
CREATE INDEX "idx_stock_enabled" ON "public"."stock" USING btree ("enabled");
