INSERT INTO "public"."stock" ("code", "name", "exchange", "enabled", "kl_types", "autypes", "tags", "notes", "created_at", "updated_at", "ipo_date", "board", "industry_l1", "full_name", "en_name", "former_names", "legal_person", "reg_capital", "found_date", "website", "email", "phone", "reg_addr", "office_addr", "postal_code", "main_business", "business_scope", "intro", "price", "total_mv", "float_mv", "pe_ttm", "pb", "turnover_rate", "main_net_inflow", "snapshot_at", "fax", "name_py") VALUES ('sh.603363', '傲农生物', '上交所', TRUE, '{}', '{}', '{}', '', '2026-09-23 02:01:57.239235+08:00', '2026-09-23 02:01:57.239235+08:00', '2017-09-26', '主板', '', '福建傲农生物科技集团股份有限公司', 'Fujian Aonong Biological Technology Group Incorporation Limited', '傲农生物>> *ST傲农', '吴有林', '273106.1826', '2011-04-26', 'www.aonong.com.cn', 'anzq@aonong.com.cn', '0596-2586018', '福建省漳州市芗城区金峰经济开发区兴亭路与宝莲路交叉处', '福建省漳州市芗城区石亭镇兴亭路与宝莲路交叉处', '363002', '养猪业务、饲料业务', '一般项目：生物饲料研发；畜牧渔业饲料销售；饲料添加剂销售；饲料原料销售；粮食收购；农业科学研究和试验发展；技术服务、技术开发、技术咨询、技术交流、技术转让、技术推广；食品销售（仅销售预包装食品）；初级农产品收购；食用农产品初加工；食用农产品批发；农副产品销售；动物肠衣加工；货物进出口；技术进出口；以自有资金从事投资活动（除依法须经批准的项目外，凭营业执照依法自主开展经营活动）。许可项目：饲料生产；饲料添加剂生产；兽药经营；食品生产；食品销售；食品互联网销售；互联网信息服务（依法须经批准的项目，经相关部门批准后方可开展经营活动，具体经营项目以相关部门批准文件或许可证件为准）', '本公司由原傲农有限整体变更设立。2015年8月18日，公司召开创立大会暨第一次股东大会，审议通过以截止2015年5月31日经审计的净资产依法整体变更设立股份有限公司。截至2015年5月31日，傲农有限净资产为217,245,784.46元，按照1:0.920616的比例折股，折为股份公司总股本200,000,000股，每股面值1元，由各股东按原各自出资比例持有，其余净资产17,245,784.46元计入资本公积。2015年8月27日，公司完成股份公司改制的工商变更登记，并换发了新的营业执照。', '2.9300', '80.0200', '62.9000', '-16.9200', '2.7000', '1.6600', '-455.6900', '2026-09-23 03:58:25.621776+08:00', '0596-2586099', 'answ'), ('sh.603370', '华新精科', '上交所', TRUE, '{}', '{}', '{}', '', '2026-09-23 02:01:57.472314+08:00', '2026-09-23 02:01:57.472314+08:00', '2025-09-05', '主板', '', '江阴华新精密科技股份有限公司', 'Jiangyin Huaxin Precision Technology Corporation', '', '郭正平', '17495.0', '2002-08-19', 'www.huaxinjk.com', 'irm@huaxinjk.com', '0510-68825536', '江苏省江阴市顾山镇新龚村云顾路137号', '江苏省江阴市顾山镇新龚村云顾路19号', '214413', '精密冲压领域产品的研发、生产和销售。', '从事电器技术的研发；生产新型片式电子元器件、精冲模、镇流器、电感器、机械模具及其零配件、金属冲压产品；以自有屋顶进行分布式光伏发电；售电；自营和代理各类商品及技术的进出口业务（国家限定企业经营或禁止进出口的商品和技术除外）。（依法须经批准的项目，经相关部门批准后方可开展经营活动）一般项目：金属材料制造；金属材料销售；塑料制品制造；塑料制品销售；新材料技术研发；电子元器件与机电组件设备制造（除依法须经批准的项目外，凭营业执照依法自主开展经营活动）。', '2015年11月12日，华新有限召开董事会，全体董事一致同意将公司整体变为股份有限公司，并确定以2015年12月31日作为审计和评估基准日。2016年4月15日，利安达会计师事务所（特殊普通合伙）出具了《审计报告》（利安达审字[2016]第2395号），确认截至2015年12月31日，华新有限的净资产额为人民币126,369,294.43元。2016年4月22日，无锡华夏中诚资产评估房地产土地估价有限公司出具《评估报告》（锡华夏评报字[2016]第019号），确认截至2015年12月31日，华新有限的净资产评估价值为15,025.29万元。2016年4月28日，北京坤元至诚资产评估有限公司出具《关于锡华夏评报字[2016]第019号的复核报告》（开元评复字[2016]002号），确认原评估报告反映的被评估企业净资产账面值为人民币12,636.93万元，评估值为人民币15,025.29万元，经复核评估，原报告评估结果合理。2016年4月22日，华新有限召开董事会，决议将江阴华新电器有限公司依法整体变更为股份有限公司，并以截至2015年12月31日经审计的全部净资产126,369,294.43元，折合为公司股本总额4,192.778965万股，每股面值1元，各发起人按原出资比例享有折合股本后的公司股份。2016年4月22日，华新科技发起人苏盛投资、华兴变压器共同签署了《江阴华新电器科技股份有限公司发起人协议书》。2016年5月10日，江阴市商务局下发了《关于同意江阴华新电器有限公司变更为外商投资股份有限公司的批复》（澄商资管字(2016)70号），同意公司变更为外商投资股份有限公司，改制后公司股本总额为4,192.778965万股，面值人民币1元。2016年5月11日，江苏省人民政府向公司换发了《中华人民共和国台港澳侨投资企业批准证书》（商外资苏府资字[2002]40903号）。2016年5月21日，华新科技召开江阴华新电器科技股份有限公司创立大会暨第一次股东大会，会议审议通过了《关于江阴华新电器科技股份有限公司筹办情况的报告》，同意以2015年12月31日为基准日，以利安达会计师事务所（特殊普通合伙）审计的净资产126,369,294.43元为依据，按照1:0.3318的比例折合为股份公司股本4,192.778965万股，余额84,441,504.78元计入股份公司的资本公积金；公司现有股东作为股份有限公司的发起人股东，所持有的股权比例不变。2016年5月27日，利安达会计师事务所（特殊普通合伙）出具《验资报告》（利安达验字[2016]第2097号），截至2016年5月27日，公司已收到全体股东以其拥有的华新有限经审计的净资产折合的股本人民币4,192.778965万元整。2024年6月26日，容诚会计师出具《验资复核报告》（容诚专字[2024]510Z0089号），确认公司折股出资情况与利安达会计师事务所（特殊普通合伙）出具的利安达验字[2016]第2097号验资报告审验结果一致。2016年6月1日，无锡市工商行政管理局核发了《营业执照》（统一社会信用代码：913202007382763297)。', '27.6200', '48.3200', '23.3300', '36.0800', '2.4700', '3.1300', '-311.4000', '2026-09-23 03:58:25.621776+08:00', '0510-68821848', 'hxjk'), ('sh.603728', '鸣志电器', '上交所', TRUE, '{}', '{}', '{}', '', '2026-09-23 02:02:04.564067+08:00', '2026-09-23 02:02:04.564067+08:00', '2017-05-09', '主板', '', '上海鸣志电器股份有限公司', 'Shanghai Moons'' Electric Co., Ltd.', '', '常建鸣', '41888.25', '1998-07-07', 'www.moons.com.cn', 'dm@moons.com.cn', '021-52634688', '上