INSERT INTO "public"."stock" ("code", "name", "exchange", "enabled", "kl_types", "autypes", "tags", "notes", "created_at", "updated_at", "ipo_date", "board", "industry_l1", "full_name", "en_name", "former_names", "legal_person", "reg_capital", "found_date", "website", "email", "phone", "reg_addr", "office_addr", "postal_code", "main_business", "business_scope", "intro", "price", "total_mv", "float_mv", "pe_ttm", "pb", "turnover_rate", "main_net_inflow", "snapshot_at", "fax", "name_py") VALUES ('sh.688836', '宇树科技', '上交所', TRUE, '{}', '{}', '{}', '', '2026-09-23 02:02:39.621510+08:00', '2026-09-23 02:02:39.621510+08:00', '2026-08-19', '科创板', '', '宇树科技股份有限公司', 'Yushu Technology Co., Ltd.', '', '王兴兴', '40446.434', '2016-08-26', 'www.unitree.com', 'ir@unitree.com', '0571-58129599', '浙江省杭州市滨江区西兴街道东流路88号1幢306室', '浙江省杭州市滨江区西兴街道东流路88号1幢306室', '310000', '高性能通用人形机器人、四足机器人、机器人组件及具身智能模型的研发、生产和销售业务。', '一般项目：技术服务、技术开发、技术咨询、技术交流、技术转让、技术推广；软件开发；软件销售；智能机器人的研发；智能机器人销售；工业机器人制造；工业机器人销售；机械设备研发；机械电气设备制造；机械设备销售；服务消费机器人制造；服务消费机器人销售；伺服控制机构制造；伺服控制机构销售；电子产品销售；机械电气设备销售；通用设备制造（不含特种设备制造）；计算机软硬件及辅助设备批发；计算机软硬件及外围设备制造；电子、机械设备维护（不含特种设备）；普通机械设备安装服务；工业机器人安装、维修；机械设备租赁；体育用品及器材批发；体育用品及器材制造；体育用品设备出租；电池制造；电池销售；电池零配件生产；电池零配件销售；互联网销售（除销售需要许可的商品）；货物进出口；技术进出口（除依法须经批准的项目外，凭营业执照依法自主开展经营活动）。许可项目：食品互联网销售；食品销售；第二类增值电信业务；出版物零售（依法须经批准的项目，经相关部门批准后方可开展经营活动，具体经营项目以审批结果为准）。', '2025年5月6日，宇树有限召开股东会，同意公司以2025年3月31日为审计和评估基准日，对宇树有限的净资产进行审计、评估，并以经审计的净资产折股的方式将宇树有限整体变更为股份有限公司。2025年5月12日，容诚会计师出具“容诚审字[2025]230Z3996号”《审计报告》，经审验，截至审计基准日2025年3月31日，宇树有限净资产为1,371,618,138.76元。同日，中水致远出具“中水致远评报字[2025]第020447号”《资产评估报告》，经评估，截至评估基准日2025年3月31日，宇树有限净资产评估值为143,295.90万元。2025年5月15日，宇树有限召开股东会，同意由宇树有限全体股东作为股份公司的发起人，将宇树有限整体变更为杭州宇树科技股份有限公司；本次整体变更以宇树有限截至2025年3月31日经审计的净资产1,371,618,138.76元为基准，按照1：0.0019的比例折为股本259.4223万股，每股面值人民币1元（注册资本为人民币259.4223万元，改制变更前后注册资本保持不变），剩余1,369,023,915.76元计入股份公司资本公积。同日，宇树有限全体股东作为发起人共同签署《发起人协议书》。2025年5月16日，宇树科技召开成立大会暨第一次临时股东会会议，会议审议通过了《关于公司整体变更为股份公司的议案》《关于股份公司筹办工作报告的议案》《关于制定<公司章程>的议案》等议案，并选举公司第一届董事会非职工董事、非职工监事。同日，公司全体发起人签署《公司章程》。2025年5月26日，容诚会计师出具了“容诚验字[2025]230Z0052号”《验资报告》，经审验，截至2025年5月16日，杭州宇树科技股份有限公司（筹）已收到全体股东缴纳的注册资本合计人民币259.4223万元，出资方式为净资产，其中：计入股本259.4223万元，其余计入资本公积。2025年5月28日，宇树有限就整体变更设立股份有限公司事宜办理完成工商变更登记手续，并取得杭州高新技术产业开发区（滨江）市场监督管理局核发的统一社会信用代码为91330108MA27YJ5H56的《营业执照》。', '489.2000', '1978.6400', '147.1900', '338.6700', '22.4900', '8.4000', '-15939.4800', '2026-09-23 03:58:25.621776+08:00', '0571-58129599', 'yskj'), ('sh.688790', '昂瑞微', '上交所', TRUE, '{}', '{}', '{}', '', '2026-09-23 02:02:38.637390+08:00', '2026-09-23 02:02:38.637390+08:00', '2025-12-16', '科创板', '', '北京昂瑞微电子技术股份有限公司', 'Beijing Onmicro Electronics Co., Ltd.', '', '钱永学', '9953.1688', '2012-07-03', 'www.onmicro.com.cn', 'ir@onmicro.com.cn', '86-10-83057600', '北京市海淀区东北旺西路8号院23号楼5层101', '北京市海淀区东北旺西路8号院23号楼5层101', '100193', '射频前端芯片、射频SoC芯片及其他模拟芯片的研发、设计与销售。', '技术开发、技术转让、技术咨询、技术服务；技术进出口、货物进出口、代理进出口；销售电子产品、计算机、软件及辅助设备、通讯设备。（市场主体依法自主选择经营项目，开展经营活动；依法须经批准的项目，经相关部门批准后依批准的内容开展经营活动；不得从事国家和本市产业政策禁止和限制类项目的经营活动。）', '2020年11月25日，中审众环出具《北京昂瑞微电子技术有限公司审计报告》（众环审字[2020]630491号），截至2020年10月31日，昂瑞微有限经审计的净资产值为55,885.38万元。2020年11月26日，华亚正信出具《北京昂瑞微电子技术有限公司拟股份制改造涉及的其净资产价值项目资产评估报告》（华亚正信评报字【2020】第A01-0068号），以2020年10月31日为评估基准日对昂瑞微有限进行评估，确定昂瑞微有限经评估的净资产值为58,811.99万元。2020年11月27日、28日，昂瑞微有限分别召开董事会和股东会并作出决议，同意以2020年10月31日为基准日，以整体变更的方式设立股份公司，昂瑞微有限整体变更后名称变更为“北京昂瑞微电子技术股份有限公司”。2020年11月28日，北京鑫科等45家发起人签署《北京昂瑞微电子技术股份有限公司之发起人协议》。2020年12月14日，发行人召开创立大会，同意以净资产折股的方式将昂瑞微有限变更为股份公司，由昂瑞微有限全体股东作为发起人，以其在昂瑞微有限的出资额对应的净资产折为发行人的全部股份。昂瑞微有限以截至2020年10月31日经审计账面净资产55,885.38万元，按照1：0.10306205的折股比例折合为发行人股本5,759.6619万股，每股面值1元，超出股本的部分计入发行人的资本公积。据此，发行人总股本为5,759.6619万股，每股面值1元，注册资本为5,759.6619万元。同日，发行人全体股东签署《北京昂瑞微电子技术股份有限公司章程》。经中审众环于2020年12月14日出具的《北京昂瑞微电子技术有限公司验资报告》（众环验字[2020]630023号）审验，截至2020年12月14日，发行人之全体发起人已按发起人协议、公司章程的规定，以昂瑞微有限股改基准日2020年10月31日的净资产折股，缴纳注册资本5,759.6619万元，超出注册资本的部分计入发行人的资本公积。2020年12月22日，发行人完成本次整体变更的工商登记。社会统一信用代码：9111010859966120XL。', '109.5800', '109.0700', '21.8100', '141.1600', '3.7100', '19.5500', '3472.5900', '2026-09-23 03:58:25.621776+08:00', '86-10-83057667', 'arw'), 