INSERT INTO "public"."stock" ("code", "name", "exchange", "enabled", "kl_types", "autypes", "tags", "notes", "created_at", "updated_at", "ipo_date", "board", "industry_l1", "full_name", "en_name", "former_names", "legal_person", "reg_capital", "found_date", "website", "email", "phone", "reg_addr", "office_addr", "postal_code", "main_business", "business_scope", "intro", "price", "total_mv", "float_mv", "pe_ttm", "pb", "turnover_rate", "main_net_inflow", "snapshot_at", "fax", "name_py") VALUES ('sh.600278', '东方创业', '上交所', TRUE, '{}', '{}', '{}', '', '2026-09-23 02:01:14.192863+08:00', '2026-09-23 02:01:14.192863+08:00', '2000-07-12', '主板', '', '东方国际创业股份有限公司', 'Orient International Enterprise, Ltd.', '', '谭明', '86051.8657', '1998-11-18', 'www.oie.com.cn', 'oiehq@oie.com.cn', '021-62789999', '上海市自由贸易试验区张杨路707号2221室', '上海市娄山关路85号A座', '200336', '服装纺织品进出口业务。', '自营和代理除国家统一组织或核定经营的进出口商品以外的商品及技术进出口业务，“三来一补”和进料加工、生物、医药、化工产品的开发、生产、销售，国际货运代理，实业和高新技术产业投资，对销贸易、转口贸易和服务贸易。批发非实物方式；预包装食品（含冷冻冷藏、不含熟食卤味），乳制品（含婴幼儿配方奶粉）。批发、零售：服装服饰、鞋帽、针织品、皮革制品、箱包、日用品。', '公司系由东方国际(集团)有限公司、东方国际集团上海市丝绸进出口有限公司、东方国际集团上海市纺织品进出口有限公司、东方国际集团上海市针织品进出口有限公司、东方国际集团上海市家用纺织品进出口有限公司、东方国际集团上海市对外贸易有限公司六家股东采取发起设立方式设立的，设立时总股本为240，00万股。其中，主要发起人东方国际集团有限公司以净资产及股权出资，折为国家股23689.05万股；其他五家发起人均以现金出资，共折为国有法人股310.95万股。经本次向社会公开发行人民币普通股8000万股后，公司总股本已达32，000万股。', '6.6000', '56.7900', '56.7900', '27.1400', '0.6700', '0.7200', '-108.7700', '2026-09-23 03:58:25.621776+08:00', '021-62784020', 'dfcy'), ('sh.600280', '中央商场', '上交所', TRUE, '{}', '{}', '{}', '', '2026-09-23 02:01:14.271235+08:00', '2026-09-23 02:01:14.271235+08:00', '2000-09-26', '主板', '', '南京中央商场(集团)股份有限公司', 'Nanjing Central Emporium (Group) Stocks Co., Ltd.', '南京中商>> 中央商场>> *ST中商', '金福', '112833.4788', '1991-06-22', 'www.njzsgroup.com', 'zyscdm@njzsgroup.com', '025-66008061、025-66008022', '江苏省南京市秦淮区中山南路79号', '江苏省南京市建邺区雨润路10号', '210041', '百货零售业以及房地产开发业务。', '一般项目：化妆品零售；钟表与计时仪器销售；箱包销售。（除依法须经批准的项目外，凭营业执照依法自主开展经营活动）。日用百货、食品、卷烟、雪茄烟零售；保健食品、针纺织品、服装鞋帽、文体用品、体育用品、体育器材、一类医疗器械、机械设备、五金交电、电子产品、家用电器、家具、装饰材料、矿产品、建材、化工产品（不含危化品）销售；房地产开发、经营；电子商务；设计、制作、代理发布国内各类广告；停车场服务；高新技术产品的开发、生产、销售；场地租赁；自营和代理各类商品及技术的进出口业务（国家限定企业经营或禁止进出口的商品和技术除外）；物业管理；美容美发；室内娱乐活动。（依法须经批准的项目，经相关部门批准后方可开展经营活动）', '中央商场”创建于抗日战争爆发前夕,当时的社会名流曾养甫、张静江、茅以升等32人发起创立了“中央商场股份有限公司”。“中央商场”于1936年正式开业,1956年在社会主义改造中实行公私合营。1964年改为国营企业。1966年8月更名为“南京市人民商场”。1987年成为南京市首批实行承包经营责任制的七家大中型企业之一。1992年4月,经批准,募集设立“南京中央商场股份有限公司”。1993年,经中国人民银行南京分行批准,公司定向募集法人股。1993年5月26日,公司募集法人股2,000万股在全国证券交易自动报价系统(“STAQ系统”)交易流通。1999年11月12日,公司1999年度第一次临时股东大会通过决议,同意停止法人股在STAQ系统流通。后经批准,公司通过上海证券交易所交易系统,于2000年9月1日至9月6日公开发行人民币普通股(A股)3,500万股。', '3.1400', '35.4300', '35.4300', '-8.5800', '14.5100', '3.3200', '-1116.5600', '2026-09-23 03:58:25.621776+08:00', '025-84717539', 'zysc'), ('sh.600281', '华阳新材', '上交所', TRUE, '{}', '{}', '{}', '', '2026-09-23 02:01:14.312649+08:00', '2026-09-23 02:01:14.312649+08:00', '2000-11-09', '主板', '', '山西华阳新材料股份有限公司', 'Shanxi Huayang New Material Co., Ltd.', '太化股份>> *ST太化>> ST太化>> 太化股份', '梁昌春', '51440.2025', '1999-02-26', 'www.hyxc600281.com', 'thgf@public.ty.sx.cn', '0351-5638038', '山西省山西转型综合改革示范区科技创新城正阳街87号', '山西省太原市长风商务区长兴南街16号太化大厦', '030021', '贵金属回收加工、石油化工设备管道工程安装、贸易业务。', '合成材料制造（不含危险化学品）；合成材料销售；新型膜材料制造；新型膜材料销售；工程塑料及合成树脂制造；工程塑料及合成树脂销售；生物基材料技术研发；生物基材料制造；生物基材料销售；塑料制品销售；基础化学原料制造（不含危险化学品等许可类化学品的制造）；化工产品生产（不含许可类化工产品）；化工产品销售（不含许可类化工产品）；专用化学产品制造（不含危险化学品）；专用化学产品销售（不含危险化学品）；污水处理及其再生利用；住房租赁；非居住房地产租赁；土地使用权租赁；服装制造；金属制品修理；通用设备修理；贵金属冶炼；新型催化材料及助剂销售；合同能源管理；技术服务、技术开发、技术咨询、技术交流、技术转让、技术推广。（除依法须经批准的项目外，凭营业执照依法自主开展经营活动）', '公司系由太原化学工业集团有限公司作为主发起人，联合山西永兴化工有限公司、太原双凯化工有限公司、山西省太原市中都物资贸易有限公司、太原美能佳化工有限公司共同发起，于1999年2月26日设立的股份有限公司。设立时公司总股本为25390.60万股。其中，主发起人以净资产出资，折为国家股24，837.60万股，另外四家发起人以现金出资，共折股为553万股。经2000年9月25日向社会公开发行人民币普通股10500万股后，公司总股本已达35890.60万股。', '4.8700', '25.0500', '25.0500', '-29.1400', '42.7700', '10.0200', '1887.7800', '2026-09-23 03:58:25.621776+08:00', '0351-5638567', 'hyxc'), ('sh.600282', '南钢股份', '上交所', TRUE, '{}', '{}', '{}', '', '2026-09-23 02:01:14.354246+08:00', '2026-09-23 02:01:14.354246+08:00', '2000-09-19', '主板', '', 