INSERT INTO "public"."stock" ("code", "name", "exchange", "enabled", "kl_types", "autypes", "tags", "notes", "created_at", "updated_at", "ipo_date", "board", "industry_l1", "full_name", "en_name", "former_names", "legal_person", "reg_capital", "found_date", "website", "email", "phone", "reg_addr", "office_addr", "postal_code", "main_business", "business_scope", "intro", "price", "total_mv", "float_mv", "pe_ttm", "pb", "turnover_rate", "main_net_inflow", "snapshot_at", "fax", "name_py") VALUES ('sh.600426', '华鲁恒升', '上交所', TRUE, '{}', '{}', '{}', '', '2026-09-23 02:01:18.517910+08:00', '2026-09-23 02:01:18.517910+08:00', '2002-06-20', '主板', '', '山东华鲁恒升化工股份有限公司', 'Shandong Hualu-Hengsheng Chemical Co., Ltd.', '', '常怀春', '274994.3015', '2000-04-25', 'www.hl-hengsheng.com', 'hlhs2465031@126.com', '0534-2465426', '山东省德州市天衢西路24号', '山东省德州市天衢西路24号', '253024', '化工产品及化学肥料的生产、销售，发电及供热业务。', '安全生产许可批准范围内的化工产品的生产、销售；许可证范围发电业务，许可证范围供热业务；化学肥料生产销售；备案范围内的进出口业务；协议并网供电业务，技术推广服务；蒸压粉煤灰砖生产销售、煤灰渣的生产销售。', '山东省鲁恒升化工股份有限公司是经山东省经济体制改革委员会鲁体改函字[2000]29号文同意，并取得了山东省人民政府鲁政股字[2000]13号《山东省股份有限公司批准证书》由山东华鲁恒升集团有限公司（以下简称华鲁恒升集团）作为主发起人，联合鲁银投资集团股份有限公司、山东德棉集团有限公司、山东省化肥工业总公司、山东省石油化工经贸集团总公司、山东华鲁国际商务中心有限公司等五家发起人共同发起设立的股份有限公司。', '20.4000', '560.9900', '560.9100', '13.6800', '1.6100', '1.0900', '-6220.5600', '2026-09-23 03:58:25.621776+08:00', '0534-2465017', 'hlhs'), ('sh.601089', '福元医药', '上交所', TRUE, '{}', '{}', '{}', '', '2026-09-23 02:01:37.332017+08:00', '2026-09-23 02:01:37.332017+08:00', '2022-06-30', '主板', '', '北京福元医药股份有限公司', 'Beijing Foyou Pharma Co., Ltd.', '', '黄河', '48000.0', '1999-02-03', 'www.foyou.com.cn', 'ir@foyou.com.cn', '010-65020399', '北京市通州区通州工业开发区广源东街8号', '北京市通州区通州工业开发区广源东街8号', '101113', '药品制剂及医疗器械的研发、生产和销售。', '许可项目：药品生产；道路货物运输（不含危险货物）；药品委托生产；药品零售；药品批发；药品进出口；药用辅料生产；药用辅料销售。（依法须经批准的项目，经相关部门批准后方可开展经营活动，具体经营项目以相关部门批准文件或许可证件为准)一般项目：医学研究和试验发展；医学研究和试验发展（除人体干细胞、基因诊断与治疗技术开发和应用）；技术服务、技术开发、技术咨询、技术交流、技术转让、技术推广。（除依法须经批准的项目外，凭营业执照依法自主开展经营活动)（不得从事国家和本市产业政策禁止和限制类项目的经营活动。）', '发行人系由发行人前身万生药业整体变更设立的股份有限公司。2018年9月21日，天健会计师事务所（特殊普通合伙）出具《北京万生药业有限责任公司审计报告》（天健审[2018]5837号），截至2018年8月31日，万生药业净资产（母公司财务报表）为人民币61,545.49万元。2019年3月18日，坤元评估出具《北京万生药业有限责任公司拟变更设立为股份有限公司涉及的相关资产及负债价值评估项目资产评估报告》（坤元评报[2019]174号）。本次资产评估采用资产基础法。经评估，截至2018年8月31日，万生药业股东全部权益的评估价值为80,318.74万元，与账面价值61,545.49万元相比评估增值18,773.25万元，增值率为30.50%。2019年4月24日，经万生药业2019年第三次临时股东会决议通过，同意“北京万生药业有限责任公司”整体变更设立为“北京福元医药股份有限公司”；以公司2018年8月31日经审计的净资产按1:0.584933226的折股比例折为股份公司股本，其中61,545.49万元净资产折合总股本为36,000.00万元，超出股本部分的净资产25,545.49万元作为公司股本溢价，计入公司资本公积；股份公司注册资本为人民币36,000万元，股份总额为36,000万股，每股面值人民币1元；公司股东以其持有公司股权所对应的净资产按照上述同一折股比例折合为股份公司股份。2019年4月24日，万生药业全体股东共同作为发起人签署了《关于变更设立北京福元医药股份有限公司之发起人协议》。2019年5月16日，公司召开创立大会，审议通过公司章程，并选举产生第一届董事会成员和第一届监事会股东代表监事。2019年5月31日，发行人在北京市通州区市场监督管理局办理工商登记，并取得注册号为91110112700216160K的《企业法人营业执照》。2019年6月19日，天健会计师事务所（特殊普通合伙）出具了“天健验[2019]183号”《验资报告》，确认截至2019年5月27日，公司已收到全体出资者所拥有的截至2018年8月31日万生药业经审计的净资产61,545.49万元，根据《公司法》的有关规定，按照公司的折股方案，将上述净资产折合实收资本36,000.00万元、资本公积25,545.49万元。', '16.4500', '78.9600', '78.9600', '20.3700', '2.1200', '0.6700', '-365.4300', '2026-09-23 03:58:25.621776+08:00', '010-65021289', 'fyyy'), ('sh.600619', '海立股份', '上交所', TRUE, '{}', '{}', '{}', '', '2026-09-23 02:01:24.376866+08:00', '2026-09-23 02:01:24.376866+08:00', '1992-11-16', '主板', '', '上海海立(集团)股份有限公司', 'Shanghai Highly (Group) Co., Ltd.', '', '李轶龙', '107334.4406', '1992-06-20', 'www.highly.cc', 'heartfelt@highly.cc', '021-58547777-7105', '上海市浦东新区金桥出口加工区宁桥路888号', '中国(上海)自由贸易试验区宁桥路888号', '201206', '制冷转子式压缩机、车用电动涡旋压缩机和制冷电机的研发、生产和销售', '研发、生产制冷设备及零部件、汽车零部件、家用电器及相关的材料、机械、电子产品，集团内关联企业产品批发及进出口业务，并提供相关配套服务，投资举办其他企业（涉及许可证经营的凭许可证经营）。', '公司前身系上海冰箱压缩机厂，1992年5月始进行股份制改组，将原公司净资产折为面值10元的国家股799.1万股，经同年6月和12月首次发行公众股和外资股，A股上市时总股份169.91万股，1992年12月10日拆细为1699.1万股(每股面值1元)；其内部职工股200万股已于1994年4月13日上市流通。', '13.6500', '146.5100', '107.7200', '72.4800', '2.3600', '4.6100', '4994.0900', '2026-09-23 03:58:25.621776+08:00', '021-50326960', 'hlgf'), ('sh.600429', '三元股份', '上交所', TRUE, '{}', '{}', '{}', '', '2026-09-23 02:01:18.599135+08:00', '2026-09-23 02:01:18.599135+08:00', '