INSERT INTO "public"."stock" ("code", "name", "exchange", "enabled", "kl_types", "autypes", "tags", "notes", "created_at", "updated_at", "ipo_date", "board", "industry_l1", "full_name", "en_name", "former_names", "legal_person", "reg_capital", "found_date", "website", "email", "phone", "reg_addr", "office_addr", "postal_code", "main_business", "business_scope", "intro", "price", "total_mv", "float_mv", "pe_ttm", "pb", "turnover_rate", "main_net_inflow", "snapshot_at", "fax", "name_py") VALUES ('sh.688595', '芯海科技', '上交所', TRUE, '{}', '{}', '{}', '', '2026-09-23 02:02:33.501644+08:00', '2026-09-23 02:02:33.501644+08:00', '2020-09-28', '科创板', '', '芯海科技(深圳)股份有限公司', 'Chipsea Technologies (Shenzhen) Corp., Ltd.', '', '卢国建', '14409.3526', '2003-09-27', 'www.chipsea.com', 'info@chipsea.com', '0755-86168545', '广东省深圳市南山区粤海街道高新区社区科苑大道深圳湾创新科技中心1栋301', '广东省深圳市南山区粤海街道科苑大道高新区社区深圳湾创新科技中心1栋301', '518000', '高精度ADC、高性能MCU、测量算法以及物联网一站式解决方案的研发设计。', '一般经营项目是：电子产品、软件与集成电路的设计、开发、销售及技术咨询，国内商业、物资供销业（以上均不含专营、专控、专卖商品）；经营进出口业务（法律、行政法规、国务院决定禁止的项目除外，限制的项目须取得许可后方可经营）。许可经营项目是：互联网信息服务；文化用品与设备的生产。', '公司设立方式为有限责任公司整体变更为股份有限公司。2015年10月30日，中兴财光华会计师事务所（特殊普通合伙）出具《审计报告》（中兴财光华审会字〔2015〕第07877号），确认截至2015年9月30日，芯海有限经审计净资产为4,555.43万元；2015年11月2日，沃克森出具《资产评估报告》沃克森评报字【2015】第0423号，确认截至2015年9月30日，芯海有限经评估净资产为4,745.91万元。2015年11月5日，芯海有限召开2015年第二次临时股东会议，同意由有限公司全体股东作为发起人，以2015年9月30日作为基准日将芯海有限整体变更为股份有限公司。2015年11月5日，芯海有限全体股东作为股份公司发起人共同签署了《发起人协议》，以芯海有限截至2015年9月30日的经审计净资产按照1:0.7903的比例折合为股份公司总股本3,600万股，每股面值为1.00元，剩余净资产部分计入资本公积。2015年11月19日，芯海科技召开创立大会暨第一次股东大会，会议决议通过上述芯海有限整体变更及折股方案。2015年11月19日，中兴财光华出具《验资报告》（中兴财光华审验字〔2015〕第07323号），确认截至2015年11月19日，各发起人对芯海科技的出资均已全部到位。2015年11月23日，深圳市市场监督管理局向芯海有限整体变更为股份公司的《营业执照》（统一社会信用代码：91440300754288784A)。', '31.9500', '46.0400', '46.0400', '-43.8600', '7.0400', '2.9600', '-179.4400', '2026-09-23 03:58:25.621776+08:00', '0755-26804983', 'xhkj'), ('sh.688596', '正帆科技', '上交所', TRUE, '{}', '{}', '{}', '', '2026-09-23 02:02:33.542587+08:00', '2026-09-23 02:02:33.542587+08:00', '2020-08-20', '科创板', '', '上海正帆科技股份有限公司', 'Shanghai Gentech Co., Ltd.', '', 'YU DONG LEI', '31767.0467', '2009-10-10', 'www.gentechindustries.com', 'ir@gentech-online.com', '021-54428800-6187', '上海市闵行区春永路55号2幢', '上海市闵行区春永路55号', '201108', '(1)气体化学品供应系统的设计、生产、安装及配套服务；(2)高纯特种气体的生产、销售；(3)洁净厂房配套系统的设计、施工。', '生产气体、化学品输送设备（特种设备除外），销售自产产品，水处理系统及洁净室厂房的设计安装，机电安装建设工程施工（涉及建筑业资质的，取得资质证书后方可从事生产经营），机电设备及管道的研发、设计、安装及服务（特种设备除外），从事电子、光纤、生物科技、节能科技、环保技术领域内的技术开发，并提供相关技术服务和技术咨询，机电产品、不锈钢制品、玻璃制品、塑料制品、金属材料（钢材、贵金属、稀有金属除外）、仪表仪器、半导体设备、光伏设备及零部件、节能产品的批发、进出口、佣金代理（拍卖除外），并提供相关的配套服务。（不涉及国营贸易管理商品，涉及配额、许可证管理商品的，按国家有关规定办理申请）。（依法需经批准的项目，经相关部门批准后方可开展经营活动）。', '2015年5月25日，正帆有限召开董事会会议，审议通过正帆有限以截至2015年4月30日经立信会计师“信会师报字[2015]第114287号”《审计报告》审计的净资产189,067,484.74元为依据，按照1：0.578471746的比例折为公司等额股份109,370,198股，每股面值1元，股本总额109,370,198元，余额79,697,286.74元计入资本公积。上述净资产已经银信评估出具的《上海正帆科技有限公司拟股份制改制净资产公允价值评估报告》“银信资评报（2015）沪第0431号”评估，截至2015年4月30日，正帆有限股东全体权益的经评估净资产为24,281.25万元，较审计后账面净资产增值3,422.45万元，增值率为16.41%，评估值大于经审计的净资产金额。2015年6月5日，正帆有限全体股东签署了《上海正帆科技股份有限公司发起人协议》及《上海正帆科技股份有限公司章程》，对正帆有限改制为股份有限公司的事项进行了确认。2015年6月29日，上海市商务委员会出具“沪商外资批[2015]2316号”《市商委关于同意上海正帆科技有限公司改制为股份有限公司的批复》，同意公司由合资企业改制为股份公司，名称为上海正帆科技股份有限公司，同意正帆有限发起人于2015年6月5日签署的发起人协议及公司章程。2015年6月30日，上海市人民政府向正帆科技核发了《中华人民共和国台港澳侨投资企业批准证书》“商外资沪股份字[2011]2417号”。2015年6月30日，立信会计师出具文号为“信会师报字[2015]第114674号”的《验资报告》，对上述改制事项进行了审验。同日，正帆科技发起人召开创立大会。2015年7月8日，正帆有限就上述整体变更事宜办理完毕相应的工商变更登记手续，领取了上海市工商行政管理局换发的股份公司营业执照（注册号：310112000926104）。2019年8月24日，容诚会计师出具的“会验字[2019]7336号”《验资复核报告》，对正帆有限在2015年整体变更为股份有限公司时委托立信会计师出具的“信会师报字[2015]第114674号”《验资报告》进行了复核。', '65.1800', '207.0600', '207.0600', '-2610.3700', '6.3700', '3.9600', '-4073.7000', '2026-09-23 03:58:25.621776+08:00', '021-54428811', 'zfkj'), ('sh.688597', '煜邦电力', '上交所', TRUE, '{}', '{}', '{}', '', '2026-09-23 02:02:33.583080+08:00', '2026-09-23 02:02:33.583080+08:00', '2021-06-17', '科创板', '', '北京煜邦电力技术股份有限公司', 'Beijing Yupont Electric Power Technology Co., Ltd.', '', '周德勤', '33606.0276', '1996-05-17', 'www.yupont.com', 'IR@yupont.com', '010-84423548', '北京市东城区和平里东街11号航星科技园航星1号楼', '北京