DROP TABLE IF EXISTS "public"."sync_job";

CREATE SEQUENCE IF NOT EXISTS "public"."sync_job_id_seq"
  AS integer
  START WITH 1
  INCREMENT BY 1
  MINVALUE 1
  MAXVALUE 2147483647
  CACHE 1
  NO CYCLE;

CREATE TABLE "public"."sync_job" (
  "id" serial NOT NULL,
  "domains" text[] NOT NULL DEFAULT '{}'::text[],
  "scope" character varying NOT NULL DEFAULT 'market'::character varying,
  "force" boolean NOT NULL DEFAULT true,
  "status" character varying NOT NULL DEFAULT 'running'::character varying,
  "started_at" timestamp with time zone NOT NULL DEFAULT now(),
  "finished_at" timestamp with time zone,
  "summary" jsonb,
  PRIMARY KEY ("id"),
  CONSTRAINT "chk_sync_job_status" CHECK (status::text = ANY (ARRAY['running'::character varying, 'interrupted'::character varying, 'done'::character varying, 'failed'::character varying]::text[]))
);

