DROP TABLE IF EXISTS "public"."stock_holder_num";

CREATE TABLE "public"."stock_holder_num" (
  "code" character varying NOT NULL,
  "stat_date" date NOT NULL,
  "notice_date" date,
  "holder_num" bigint,
  "prev_holder_num" bigint,
  "holder_num_change" bigint,
  "holder_num_change_pct" numeric(12,4),
  "avg_hold_mv" numeric(18,4),
  "avg_hold_shares" numeric(18,4),
  "total_share" numeric(18,4),
  "updated_at" timestamp with time zone NOT NULL DEFAULT now(),
  PRIMARY KEY ("code", "stat_date"),
  CONSTRAINT "stock_holder_num_code_fkey" FOREIGN KEY ("code") REFERENCES "stock"("code")
);
