DROP TABLE IF EXISTS "public"."stock_industry";

CREATE TABLE "public"."stock_industry" (
  "code" character varying NOT NULL,
  "industry_name" character varying NOT NULL,
  "rank" integer NOT NULL DEFAULT 0,
  "is_primary" boolean NOT NULL DEFAULT false,
  PRIMARY KEY ("code", "industry_name"),
  CONSTRAINT "stock_industry_code_fkey" FOREIGN KEY ("code") REFERENCES "stock"("code")
);
CREATE INDEX "idx_si_industry" ON "public"."stock_industry" USING btree ("industry_name");

INSERT INTO "public"."stock_industry" ("code", "industry_name", "rank", "is_primary") VALUES ('sz.000001', '货币金融服务', 0, TRUE), ('sh.600519', '酒、饮料和精制茶制造业', 0, TRUE);

DROP TABLE IF EXISTS "public"."watchlist_item";

CREATE TABLE "public"."watchlist_item" (
  "folder_id" integer NOT NULL,
  "code" character varying NOT NULL,
  "added_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "watchlist_item_folder_id_fkey" FOREIGN KEY ("folder_id") REFERENCES "watchlist_folder"("id")
);
CREATE INDEX "idx_wl_code" ON "public"."watchlist_item" USING btree ("code");
CREATE INDEX "idx_wl_folder_id" ON "public"."watchlist_item" USING btree ("folder_id");
CREATE UNIQUE INDEX "watchlist_item_folder_id_code_key" ON "public"."watchlist_item" USING btree ("folder_id", "code");

